<div class="top"><h1>Tableau de bord</h1><span class="muted"><?= date('d/m/Y') ?></span></div>
<?php foreach ($todo as $t): ?><div class="alert a-warn"><?= e($t) ?></div><?php endforeach; ?>
<?php if ($demo): ?><div class="alert a-info"><b><?= $demo ?> produit(s)</b> ont encore un tarif de démonstration. <a href="/admin/produits?price=demo"><b>Les vérifier et confirmer les prix →</b></a></div><?php endif; ?>
<div class="stats"><?php foreach ($stats as $l => $v): ?><div class="stat"><small><?= e($l) ?></small><strong><?= is_int($v) ? $v : $v ?></strong></div><?php endforeach; ?></div>
<?php if ($fin): ?><div class="card"><h2>Ventes des 30 derniers jours (FCFA)</h2><?php $max = max(1, max($days)); ?><div class="chart"><?php foreach ($days as $d => $v): ?><div style="height:<?= max(2, round($v / $max * 100)) ?>%" data-v="<?= e(substr($d, 8, 2) . '/' . substr($d, 5, 2) . ' : ' . money($v)) ?>"></div><?php endforeach; ?></div><div class="chart-l"><span><?= substr(array_key_first($days), 8, 2) ?>/<?= substr(array_key_first($days), 5, 2) ?></span><span style="text-align:right"><?= date('d/m') ?></span></div></div>
<?php endif; ?>
<div class="grid g2"><?php if ($fin): ?><div class="card"><h2>Produits les plus vendus</h2><?php if ($top): ?><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Produit</th><th>Qté</th><th class="right">CA</th></tr></thead><tbody><?php foreach ($top as $t): ?><tr><td><?= e($t['name']) ?></td><td><?= (int) $t['q'] ?></td><td class="right"><?= money($t['t']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted">Pas encore de ventes.</p><?php endif; ?></div><?php endif; ?>
<?php if ($ord): ?><div class="card"><h2>Dernières commandes</h2><?php if ($recent): ?><div class="tbl-wrap"><table class="tbl"><tbody><?php foreach ($recent as $o): ?><tr><td><a href="/admin/commandes/<?= (int) $o['id'] ?>"><b><?= e($o['ref']) ?></b></a><br><small class="muted"><?= e($o['name']) ?></small></td><td><?= status_badge(order_status_all(), $o['status']) ?></td><td class="right"><?= money($o['total']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted">Aucune commande.</p><?php endif; ?></div><?php endif; ?></div>